pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testRegression_property() public {
        address baseToken = address(0x123);
        address nft = address(0x456);

        c.initialize(
            baseToken,
            nft,
            1000 ether,
            100,
            0,
            500,
            bytes32(0),
            false,
            false
        );

        address actualBaseToken = c.baseToken();

        assertTrue(actualBaseToken == address(0x123), "baseToken should be 0x123, not zero");
    }
}
